slots.drawFrame:
const rod = state.e0;
const half = Math.max(rod.w, rod.h) / 2;
const yTop = rod.cy + half;
const yBot = rod.cy - half;
const xL = 0.30;
const xR = 9.70;

// 竖直方向匀强磁场（俯视等效：垂直纸面）
Draw.fieldDots({ x: xL + 0.25, y: yBot + 0.05, w: (xR - xL) - 0.5, h: 2 * half - 0.1 }, { symbol: 'dot', nx: 18, ny: 4 });

// 平行金属导轨（比金属棒活动范围更宽）
Draw.line([xL, yTop], [xR, yTop], { width: 3 });
Draw.line([xL, yBot], [xR, yBot], { width: 3 });

// 左端回路：开关支路（最左竖直导线 + 开关）
Draw.line([xL, yTop], [xL, rod.cy + 0.24], { width: 2 });
Draw.line([xL, rod.cy - 0.24], [xL, yBot], { width: 2 });
Draw.circle([xL, rod.cy + 0.24], 0.05);
Draw.circle([xL, rod.cy - 0.24], 0.05);
Draw.line([xL, rod.cy + 0.20], [xL + 0.13, rod.cy - 0.14], { width: 2 });

// 电容支路（与开关支路并联）
const xC = xL + 0.19;
Draw.line([xC, yTop], [xC, rod.cy + 0.08], { width: 2 });
Draw.line([xC, rod.cy - 0.08], [xC, yBot], { width: 2 });
Draw.line([xC - 0.09, rod.cy + 0.08], [xC + 0.09, rod.cy + 0.08], { width: 3 });
Draw.line([xC - 0.09, rod.cy - 0.08], [xC + 0.09, rod.cy - 0.08], { width: 3 });

// 定值电阻 R（串在上导轨左端）
Draw.box([0.72, yTop], 0.26, 0.16);

// 金属棒（竖直跨接在两导轨之间，随 state 平移）
Draw.line([rod.cx, yBot], [rod.cx, yTop], { width: 4 });
Draw.circle([rod.cx, yTop], 0.05);
Draw.circle([rod.cx, yBot], 0.05);

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(1.386294, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "conductor_rod.x", label: "conductor_rod 水平位置", value: state.e0.x, unit: 'm' });
out.push({ key: "conductor_rod.y", label: "conductor_rod 竖直位置", value: state.e0.y, unit: 'm' });
out.push({ key: "conductor_rod.vx", label: "conductor_rod 水平速度", value: (b.e0.x - a.e0.x) / dt, unit: 'm/s' });
out.push({ key: "conductor_rod.vy", label: "conductor_rod 竖直速度", value: (b.e0.y - a.e0.y) / dt, unit: 'm/s' });
return out;
